#!/usr/bin/env node
/*
 * Render one-screen previews of back-office (admin) screens in back-office looks (assets/backoffice/styles.json) that differ in
 * density, structure, tone and edge treatment, so a team can choose from pictures
 * (references/back-office.md "Choosing density and tone from pictures").
 *
 * Usage:
 *   node scripts/backoffice_preview.js [--styles calm,dense | --direction dose,editorial] [--screens records,approval]
 *        [--out dir] [--width 1440] [--height 900] [--sheet] [--thai] [--singles records,approval|all]
 *        [--mobile]   # 390 x 844 phone set: records, approval, overview, inbox, detail, form, menu (drawer),
 *                     # filter (bottom sheet), states (loading/empty/error), components (bottom nav, FAB, sheet…)
 *
 * Screens (layout IDs in assets/layouts/admin.md and dashboards.md):
 *   records   A01 record management      approval  A03 approval workbench
 *   audit     A06 audit log              overview  D01 operational overview
 *   access    A04 access management      settings  A07 settings with save behaviour
 *   detail    A02 record detail          import    A05 import wizard
 *   finance   D03 finance report         incidents D04 monitoring and incidents
 *   inbox     P01 inbox / task queue     kanban    P02 workflow board
 *   form      create / edit payment      analytics D02 analytics
 *   compare   D05 period comparison      heatmap   D06 matrix / heatmap
 *   status    (no layout ID) service status: uptime strips, resource cards, ring meters, ranked bars
 *   signin    sign-in                    denied    403 no access          notfound  404
 *   components  every component with its states, as a library sheet (full page)
 *   advanced    editable grid, drag reorder, color picker, rich text, mention/tag, notification centre,
 *               onboarding tour, autosave form, password recovery, interaction-state matrix (full page)
 *   states      loading, empty, error, no permission, bulk partial failure, stale data (full page)
 * Tablet: --width 820 --height 1366 (side nav becomes a rail, secondary columns hide).
 * RTL: --rtl mirrors the layout (dir=rtl); strings stay English, so it checks layout only.
 * Sixteen looks (assets/backoffice/styles.json) differ in nav (side | rail | top), table style
 * (zebra | lines | cards | plain), status tag (pill | square | dot), edges, density and colour.
 * Every screen fills the viewport with realistic sample data (a payments back office, labelled as
 * sample), one inline icon set, charts with axes and gridlines, selection, row actions and a pager.
 * They show layout, density, hierarchy, status treatment (text + shape, never colour alone), money
 * alignment and masking. They are NOT a tested screen: keyboard, focus order and loading, empty,
 * error and permission states still need a rendered build. Fonts load from Google Fonts (network).
 * Single images are kept only for --singles (default records,approval; "all" keeps every one);
 * --sheet writes sheet-<screen>.jpg (all looks side by side; --style-sheets also writes sheet-<style>.jpg).
 * components and states are always kept as full-page singles.
 */
const fs = require('fs');
const path = require('path');
const { findModule, findBrowser } = require('./_pw');
const args = process.argv.slice(2);
const opt = (k, d) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : d; };
const has = k => args.includes(k);
const root = path.resolve(__dirname, '..');
const styles = JSON.parse(fs.readFileSync(path.join(root, 'assets/backoffice/styles.json'), 'utf8')).styles;
const out = path.resolve(opt('--out', path.join(root, 'assets/backoffice/previews')));
const mobile = has('--mobile');
const W = Number(opt('--width', mobile ? '390' : '1440')), H = Number(opt('--height', mobile ? '844' : '900'));
const thai = has('--thai');
const singles = opt('--singles', 'records,approval');
const SCREENS = mobile ? ['records', 'approval', 'overview', 'inbox', 'detail', 'form', 'menu', 'filter', 'states', 'components'] : ['records', 'approval', 'audit', 'overview', 'access', 'settings', 'detail', 'import', 'finance', 'incidents', 'inbox', 'kanban', 'form', 'analytics', 'compare', 'heatmap', 'status', 'signin', 'denied', 'notfound', 'components', 'advanced', 'states'];
const TALL = ['components', 'advanced', 'states'];
// --direction <id,…>: the admin screens of a brand direction (scripts/brand.js), same tokens as its public pages
const brand = require('./brand');
const directions = JSON.parse(fs.readFileSync(path.join(root, 'assets/directions/directions.json'), 'utf8')).directions;
const pickS0 = opt('--direction') ? directions.filter(d => opt('--direction') === 'all' || opt('--direction').split(',').includes(d.id)).map(d => brand.productStyle(d, styles))
  : opt('--styles') ? styles.filter(s => opt('--styles').split(',').includes(s.id)) : styles;
const pickS = pickS0.map(s => (!mobile && W < 1100 && s.nav === 'side') ? Object.assign({}, s, { nav: 'rail' }) : s); // tablet: side nav collapses to a rail
const pickC = opt('--screens') ? SCREENS.filter(s => opt('--screens').split(',').includes(s)) : SCREENS;
if (!pickS.length || !pickC.length) { console.error('nothing matched'); process.exit(2); }

