/* ---- more charts ---- */
function lineChart(s, a, b, labels) {
  const x0 = 46, x1 = 636, y0 = 14, y1 = 208, max = 100, w = (x1 - x0) / (a.length - 1);
  const pts = v => v.map((d, i) => `${x0 + i * w},${y1 - (d / max) * (y1 - y0)}`).join(' ');
  const grid = [0, 25, 50, 75, 100].map(f => { const y = y1 - (f / max) * (y1 - y0); return `<line x1="${x0}" x2="${x1}" y1="${y}" y2="${y}" stroke="${s.dark ? '#2e343d' : '#dfe3e8'}"/><text x="${x0 - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="${s.muted}">${f}</text>`; }).join('');
  const lab = labels.map((l, i) => (i % 3 === 0 ? `<text x="${x0 + i * w}" y="228" text-anchor="middle" font-size="11" fill="${s.muted}">${l}</text>` : '')).join('');
  const area = `${x0},${y1} ${pts(a)} ${x1},${y1}`;
  const last = a.length - 1;
  return `<svg viewBox="0 0 640 238" style="width:100%;flex:1;min-height:0" preserveAspectRatio="none">${grid}<defs><linearGradient id="lga" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${s.accent}" stop-opacity=".34"/><stop offset="1" stop-color="${s.accent}" stop-opacity="0"/></linearGradient></defs><polygon points="${area}" fill="url(#lga)"/><polyline points="${pts(b)}" fill="none" stroke="${s.muted}" stroke-width="2" stroke-dasharray="5 4"/><polyline points="${pts(a)}" fill="none" stroke="${s.accent}" stroke-width="2.6" stroke-linejoin="round" stroke-linecap="round"/><circle cx="${x0 + last * w}" cy="${y1 - (a[last] / max) * (y1 - y0)}" r="5" fill="${s.accent}" stroke="${s.surface}" stroke-width="2"/>${lab}</svg>`;
}
function groupBars(s, a, b, labels) {
  const x0 = 46, x1 = 636, y0 = 14, y1 = 208, max = 100, w = (x1 - x0) / a.length;
  const grid = [0, 25, 50, 75, 100].map(f => { const y = y1 - (f / max) * (y1 - y0); return `<line x1="${x0}" x2="${x1}" y1="${y}" y2="${y}" stroke="${s.dark ? '#2e343d' : '#dfe3e8'}"/><text x="${x0 - 8}" y="${y + 4}" text-anchor="end" font-size="11" fill="${s.muted}">${f}</text>`; }).join('');
  const bars = a.map((v, i) => { const bw = w * 0.3, x = x0 + i * w + w * 0.15, h1 = (v / max) * (y1 - y0), h2 = (b[i] / max) * (y1 - y0); return `<rect x="${x}" y="${y1 - h2}" width="${bw}" height="${h2}" rx="${Math.min(s.cr, 5)}" fill="${s.dark ? '#46506a' : s.accentSoft}"/><rect x="${x + bw + 3}" y="${y1 - h1}" width="${bw}" height="${h1}" rx="${Math.min(s.cr, 5)}" fill="${s.accent}"/><text x="${x + bw}" y="228" text-anchor="middle" font-size="11" fill="${s.muted}">${labels[i]}</text>`; }).join('');
  return `<svg viewBox="0 0 640 238" style="width:100%;flex:1;min-height:0" preserveAspectRatio="none">${grid}${bars}</svg>`;
}
const legend = (s, items) => `<span class="muted bar" style="margin-left:auto;gap:14px">${items.map((t, i) => `<span class="bar" style="gap:6px"><i style="width:12px;height:12px;border-radius:3px;display:inline-block;background:${i === 0 ? s.accent : (s.dark ? '#46506a' : s.accentSoft)}"></i>${t}</span>`).join('')}</span>`;

