screens.compare = s => shell(s, 0, `<div class="page">${head(s, T.compare, T.compareSub, `<span class="btn">${ic('calendar', 16)}${T.series[0]} ${L('vs', 'เทียบ')} ${T.series[1]}${ic('chevron', 14)}</span>`, [T.nav[0], T.compare])}
<div class="grid2" style="grid-template-columns:1.3fr 1fr"><div class="card cardf" style="padding:18px 20px"><div class="bar"><b>${L('Paid by week (฿ thousand)', 'จ่ายรายสัปดาห์ (พันบาท)')}</b>${legend(s, [T.series[0], T.series[1]])}</div>${groupBars(s, [62, 70, 84, 96], [58, 64, 70, 78], ['W1', 'W2', 'W3', 'W4'])}</div>
<div class="card cardf" style="padding:4px 0"><table class="t"><thead><tr>${T.cmpCols.map((c, i) => `<th class="${i ? 'num' : ''}">${c}</th>`).join('')}</tr></thead><tbody>${[['Siam Fresh Co.', '120,400', '148,200', 23], ['Lanna Print', '58,900', '52,300', -11], ['Chao Phraya Logistics', '301,000', '326,900', 9], ['Baan Coffee', '8,200', '8,900', 9], ['Northwind Clinic', '96,000', '95,000', -1], ['Mango Soda Ltd.', '12,000', '21,300', 78]].slice(0, Math.max(4, Math.min(6, Math.floor((H - 520) / s.rowH)))).map(r => `<tr><td>${r[0]}</td><td class="num">${r[1]}</td><td class="num">${r[2]}</td><td class="num" style="color:${r[3] < 0 ? s.bad[0] : s.ok[0]};font-weight:700">${r[3] < 0 ? '▼' : '▲'} ${Math.abs(r[3])}%</td></tr>`).join('')}</tbody></table></div></div></div>`);

screens.heatmap = s => { const v = (d, h) => Math.round(((Math.sin(d * 1.7 + h * 0.9) + 1) * 3.2 + (h >= 5 && h <= 8 ? 6 : 0) + (d > 4 ? -2 : 0))); const hours = Array.from({ length: 12 }, (_, i) => i + 8); const cell = x => { const a = Math.min(1, Math.max(0.06, x / 12)); return `<span style="background:color-mix(in oklab,${s.accent} ${Math.round(a * 100)}%,${s.surface});color:${a > 0.5 ? s.accentInk : s.ink}">${Math.max(0, x)}</span>`; };
  return shell(s, 0, `<div class="page">${head(s, T.heatmap, T.heatmapSub, `<span class="btn">${ic('calendar', 16)}${T.range}${ic('chevron', 14)}</span>`, [T.nav[0], T.heatmap])}<div class="card cardf" style="padding:22px 24px;gap:10px;flex:1"><div class="heat hd"><span></span>${hours.map(h => `<span class="muted" style="font-weight:500;height:24px">${h}:00</span>`).join('')}</div>${T.days.map((d, di) => `<div class="heat"><span class="muted" style="font-weight:600">${d}</span>${hours.map((h, hi) => cell(v(di, hi))).join('')}</div>`).join('')}
<div class="bar" style="margin-top:auto;gap:6px"><span class="muted">${T.legend}</span><span class="bar" style="gap:4px;margin-left:12px">${[0, 3, 6, 9, 12].map(x => `<span style="width:34px;height:22px;border-radius:4px;background:color-mix(in oklab,${s.accent} ${Math.round(Math.max(0.06, x / 12) * 100)}%,${s.surface});display:grid;place-items:center;font-size:11px;color:${x > 6 ? s.accentInk : s.ink}">${x}</span>`).join('')}</span></div></div></div>`); };


screens.status = s => {
  const strip = (seed, bad) => `<div class="strip">${Array.from({ length: 72 }, (_, i) => { const x = (i * 7 + seed * 13) % 71; const c = bad.includes(i) ? s.bad[0] : (x === 3 ? s.warn[0] : s.ok[0]); return `<i style="background:${c}"></i>`; }).join('')}</div>`;
  const meter = (label, v) => { const c = v > 85 ? s.bad[0] : v > 70 ? s.warn[0] : s.ok[0]; return `<div style="display:grid;grid-template-columns:54px 1fr 38px;gap:10px;align-items:center" class="muted"><span>${label}</span><span style="height:6px;border-radius:99px;background:color-mix(in oklab,${s.ink} 10%,${s.surface});overflow:hidden"><i style="display:block;height:100%;width:${v}%;background:${c};border-radius:99px"></i></span><b class="mono" style="color:${s.ink}">${v}%</b></div>`; };
  const ring = (v, label) => { const r = 30, c = 2 * Math.PI * r; return `<div style="display:flex;flex-direction:column;align-items:center;gap:8px;flex:1"><svg width="86" height="86" viewBox="0 0 86 86"><circle cx="43" cy="43" r="${r}" fill="none" stroke="color-mix(in oklab,${s.ink} 10%,${s.surface})" stroke-width="7"/><circle cx="43" cy="43" r="${r}" fill="none" stroke="${s.accent}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${(v / 100) * c} ${c}" transform="rotate(-90 43 43)"/><text x="43" y="48" text-anchor="middle" font-size="16" font-weight="700" fill="${s.ink}" style="font-variant-numeric:tabular-nums">${v}%</text></svg><span class="muted" style="font-size:12px">${label}</span></div>`; };
  const rank = [['/v1/payments', 840], ['/v1/export', 720], ['/v1/search', 510], ['/v1/login', 340], ['/v1/health', 90]];
  const hosts = [['web-prod-01', 42, 61, 38], ['db-replica-03', 78, 88, 54], ['cache-02', 24, 35, 18]];
  return shell(s, 0, `<style>.strip{display:flex;gap:2px;height:30px}.strip i{flex:1;border-radius:2px;opacity:.9}</style><div class="page">${head(s, T.status, T.statusSub, `<span class="chip" style="color:${s.ok[0]};background:${s.ok[1]}">● ${T.allOk}</span>`, [T.nav[0], T.status])}
<div class="grid2" style="grid-template-columns:1fr 360px;gap:16px"><div style="display:flex;flex-direction:column;gap:16px;min-height:0">
<div class="card" style="padding:20px 22px;display:flex;flex-direction:column;gap:16px">${T.svc.map((n, i) => `<div><div class="bar" style="margin-bottom:8px"><b>${n}</b><span class="mono" style="margin-left:auto;color:${[s.ok[0], s.ok[0], s.ok[0], s.warn[0]][i]}">${['99.98', '100.00', '99.96', '99.91'][i]}%</span></div>${strip(i + 1, i === 3 ? [40, 41] : [])}</div>`).join('')}<div class="bar muted" style="font-size:12px"><span>${T.ago}</span><span style="margin-left:auto">${T.today}</span></div></div>
<div class="card" style="padding:20px 22px;display:flex;gap:10px">${T.rings.map((l, i) => ring([96, 88, 64, 93][i], l)).join('')}</div></div>
<div style="display:flex;flex-direction:column;gap:16px;min-height:0">
${hosts.map(h => `<div class="card" style="padding:16px 18px;display:flex;flex-direction:column;gap:10px"><div class="bar"><b class="mono">${h[0]}</b><span class="chip" style="margin-left:auto;color:${(h[1] > 70 ? s.warn : s.ok)[0]};background:${(h[1] > 70 ? s.warn : s.ok)[1]}">${h[1] > 70 ? '◔' : '●'}</span></div>${meter('CPU', h[1])}${meter('MEM', h[2])}${meter('DISK', h[3])}</div>`).join('')}
<div class="card" style="padding:16px 18px;display:flex;flex-direction:column;gap:9px"><b>${T.ranked}</b>${rank.map(r => `<div style="display:grid;grid-template-columns:96px 1fr 52px;gap:8px;align-items:center" class="muted"><span class="mono">${r[0]}</span><span style="height:8px;border-radius:99px;background:${s.accent};width:${(r[1] / 840) * 100}%"></span><b class="mono" style="color:${s.ink};text-align:right">${r[1]}ms</b></div>`).join('')}</div></div></div></div>`); };
const bare = (s, inner) => { const fams = [...new Set([s.font, s.displayFont, 'DM Mono', 'Noto Sans Thai'].filter(Boolean))].map(f => 'family=' + f.replace(/ /g, '+')).join('&'); return `<!doctype html><html><head><meta charset="utf-8"><link href="https://fonts.googleapis.com/css2?${fams}&display=swap" rel="stylesheet"><style>${css(s)}body{display:grid;place-items:center}</style></head><body>${inner}</body></html>`; };
