Object.assign(T, {
  more: L('More', 'เพิ่มเติม'), menu: L('Menu', 'เมนู'), filtersT: L('Filters', 'ตัวกรอง'), apply: L('Show 38 results', 'แสดง 38 รายการ'), clearAll: L('Clear all', 'ล้างทั้งหมด'), swipe: L('Approve', 'อนุมัติ'),
  greet: L('Good afternoon, Napa', 'สวัสดีตอนบ่าย คุณนภา'), snack: L('Payment approved', 'อนุมัติรายการแล้ว'), undo: L('Undo', 'เลิกทำ'), pull: L('Pull to refresh', 'ดึงลงเพื่อรีเฟรช'), statusF: L('Status', 'สถานะ'), dateF: L('Date', 'วันที่'), methodF: L('Method', 'วิธีจ่าย'),
  mnav: L(['Home', 'Payments', 'Approvals', 'Audit', 'More'], ['หน้าแรก', 'จ่ายเงิน', 'อนุมัติ', 'บันทึก', 'เพิ่มเติม'])
});
const MSCREENS = ['records', 'approval', 'overview', 'inbox', 'detail', 'form', 'menu', 'filter', 'states', 'components'];
const MNAV = ['overview', 'payments', 'approvals', 'audit', 'more'];
IC.more2 = '<path d="M4 7h16M4 12h16M4 17h16"/>'; IC.close = '<path d="m6 6 12 12M18 6 6 18"/>'; IC.back = '<path d="m15 5-7 7 7 7"/>';
function mcss(s) {
  const bd = s.edge === 'strong' ? '2px solid var(--ink)' : s.edge === 'line' ? '1px solid var(--ln)' : 'none';
  const tb = s.edge === 'strong' ? '2px solid var(--ink)' : '1px solid var(--ln)';
  const barBg = s.sideDark ? s.side : s.surface, barFg = s.sideDark ? (s.dark ? s.ink : '#fff') : s.ink;
  return `
:root{--g:${s.ground};--sf:${s.surface};--ink:${s.ink};--m:${s.muted};--ln:${s.line};--a:${s.accent};--ai:${s.accentInk};--as:${s.accentSoft};--r:${s.radius}px;--cr:${s.cr}px;--br:${s.br}px;--fr:${s.fr}px;--nr:${s.nr}px;--avr:${s.av};--cbr:${s.cb}px}
*{box-sizing:border-box;margin:0}
body{width:390px;height:844px;overflow:hidden;position:relative;background:var(--g);color:var(--ink);font:400 16px/1.45 "${s.font}","Noto Sans Thai",system-ui,sans-serif}
.ic{flex:none}
.sbar{height:28px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;font:600 13px "DM Mono",monospace;background:${barBg};color:${barFg}}
.app{height:56px;display:flex;align-items:center;gap:6px;padding:0 8px 0 4px;background:${barBg};color:${barFg};${s.edge === 'tone' ? '' : 'border-bottom:' + tb + ';'}}
.app h1{font:700 19px/1.2 "${s.font}","Noto Sans Thai",sans-serif;flex:1;padding-left:8px}
.app .ib{width:44px;height:44px;display:grid;place-items:center;border-radius:50%;position:relative}
.app .ib i{position:absolute;top:9px;right:10px;width:9px;height:9px;border-radius:50%;background:${s.bad[0]};border:2px solid ${barBg}}
.scr{position:absolute;top:84px;bottom:76px;left:0;right:0;overflow:hidden;padding:14px 16px;display:flex;flex-direction:column;gap:12px}
.bnav{position:absolute;left:0;right:0;bottom:0;height:76px;background:var(--sf);${s.edge === 'tone' ? 'box-shadow:0 -6px 20px rgba(0,0,0,' + (s.dark ? '.35' : '.07') + ');' : 'border-top:' + tb + ';'}display:flex;padding:8px 6px 14px}
.bnav a{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;font-weight:600;color:var(--m);position:relative;min-height:44px}
.bnav a .pill{height:30px;width:58px;border-radius:99px;display:grid;place-items:center}
.bnav a.on{color:var(--ink)}.bnav a.on .pill{background:var(--as);color:var(--ink)}
.bnav .bd{position:absolute;top:-2px;left:50%;margin-left:8px;min-width:18px;height:18px;border-radius:99px;background:${s.bad[0]};color:#fff;font-size:11px;display:grid;place-items:center;padding:0 5px}
.fab{position:absolute;right:16px;bottom:92px;height:56px;min-width:56px;border-radius:min(calc(var(--br) + 8px),28px);background:var(--a);color:var(--ai);display:flex;align-items:center;justify-content:center;gap:8px;padding:0 18px;font-weight:700;box-shadow:0 8px 20px rgba(0,0,0,${s.dark ? '.5' : '.25'})}
.card{border-radius:var(--cr);background:var(--sf);border:${bd}}
.bar{display:flex;align-items:center;gap:10px}.muted{color:var(--m)}.mono{font-family:"DM Mono",monospace;font-variant-numeric:tabular-nums;font-size:14px}
.btn{height:48px;padding:0 18px;display:inline-flex;align-items:center;justify-content:center;gap:8px;border-radius:var(--br);background:var(--sf);color:var(--ink);border:${s.edge === 'strong' ? '2px solid var(--ink)' : '1px solid var(--ln)'};font-weight:700;font-size:16px;white-space:nowrap}
.btn.p{background:var(--a);color:var(--ai);border-color:var(--a)}.btn.full{flex:1}
.chip{display:inline-flex;gap:6px;align-items:center;padding:3px 10px;font-weight:600;font-size:13px;white-space:nowrap;${s.edge === 'strong' ? 'border:1.5px solid currentColor;' : ''}}
.fc{height:36px;padding:0 14px;border-radius:99px;display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:14px;background:var(--sf);border:1px solid var(--ln);white-space:nowrap;flex:none}.fc.on{background:var(--as);border-color:var(--a)}
.avs{width:30px;height:30px;border-radius:var(--avr);background:var(--as);color:var(--ink);display:inline-grid;place-items:center;font-size:12px;font-weight:700;flex:none}
.item{padding:14px;display:flex;flex-direction:column;gap:8px}
.flag{border-radius:var(--cr);padding:11px 14px;display:flex;gap:10px;align-items:flex-start;font-weight:600;font-size:15px}
.field{height:52px;border-radius:var(--fr);border:${s.edge === 'strong' ? '2px solid var(--ink)' : '1px solid var(--m)'};background:var(--sf);padding:0 14px;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:16px}
.skel{background:var(--ln);border-radius:6px;height:14px}.spin{width:20px;height:20px;border-radius:50%;border:3px solid var(--ln);border-top-color:var(--a);display:inline-block}
.kv{display:grid;grid-template-columns:120px 1fr;gap:8px 12px;font-size:15px}
.tabs{display:flex;gap:4px;overflow:hidden;${s.edge === 'tone' ? '' : 'border-bottom:' + tb + ';'}}.tab{padding:10px 14px;font-weight:700;color:var(--m);white-space:nowrap}.tab.on{color:var(--ink);box-shadow:inset 0 -3px 0 var(--a)}
.tl{display:flex;flex-direction:column;gap:14px}.tl div{display:flex;gap:12px}.tl b{font-family:"DM Mono",monospace;color:var(--m);font-weight:500;min-width:48px;font-size:13px}.tl span::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--a);margin-right:8px}
.sheet{position:absolute;left:0;right:0;bottom:0;background:var(--sf);border-radius:20px 20px 0 0;padding:10px 16px 22px;box-shadow:0 -12px 40px rgba(0,0,0,.28);display:flex;flex-direction:column;gap:14px;z-index:5}
.sheet .grab{width:40px;height:5px;border-radius:99px;background:var(--ln);margin:0 auto}
.scrim{position:absolute;inset:0;background:rgba(0,0,0,.45);z-index:4}
.drawer{position:absolute;top:0;bottom:0;left:0;width:300px;background:${barBg};color:${barFg};z-index:5;padding:40px 12px 16px;display:flex;flex-direction:column;gap:4px;box-shadow:12px 0 40px rgba(0,0,0,.35)}
.drawer a{display:flex;align-items:center;gap:14px;height:48px;padding:0 14px;border-radius:var(--nr);font-weight:600}.drawer a.on{background:var(--a);color:var(--ai)}
.decide{position:absolute;left:0;right:0;bottom:0;padding:12px 16px 24px;background:var(--sf);${s.edge === 'tone' ? 'box-shadow:0 -8px 24px rgba(0,0,0,' + (s.dark ? '.4' : '.08') + ');' : 'border-top:' + tb + ';'}display:flex;gap:10px;z-index:3}
.swipe{position:relative;overflow:hidden;border-radius:var(--cr)}.swipe .act{position:absolute;inset:0;background:${s.ok[0]};color:#fff;display:flex;align-items:center;padding:0 18px;gap:8px;font-weight:700}.swipe .row{position:relative;transform:translateX(128px);background:var(--sf)}
.kpi{padding:14px;display:flex;flex-direction:column;gap:4px}.kpi .v{font:700 26px/1.1 "${s.font}","Noto Sans Thai",sans-serif;font-variant-numeric:tabular-nums}
.tog{display:inline-block;width:48px;height:28px;border-radius:99px;background:var(--a);position:relative;flex:none}.tog::after{content:"";position:absolute;right:3px;top:3px;width:22px;height:22px;border-radius:50%;background:var(--ai)}.tog.off{background:var(--ln)}.tog.off::after{left:3px;right:auto;background:var(--sf)}
.snack{position:absolute;left:12px;right:12px;bottom:90px;background:${s.dark ? '#e6e9ec' : '#1d2230'};color:${s.dark ? '#14171d' : '#fff'};padding:14px 16px;border-radius:var(--r);display:flex;gap:12px;align-items:center;z-index:3}
`;
}
const mphone = (s, title, body, opts = {}) => {
  const fams = [...new Set([s.font, s.displayFont, 'DM Mono', 'Noto Sans Thai'].filter(Boolean))].map(f => 'family=' + f.replace(/ /g, '+')).join('&');
  const back = opts.back;
  const app = opts.noApp ? '' : `<div class="app">${back ? `<span class="ib">${ic('back', 22)}</span>` : `<span class="ib">${ic('more2', 22)}</span>`}<h1>${title}</h1>${opts.search === false ? '' : `<span class="ib">${ic('search', 21)}</span>`}<span class="ib">${ic('bell', 21)}<i></i></span></div>`;
  const nav = opts.noNav ? '' : `<div class="bnav">${T.mnav.map((n, i) => `<a class="${i === (opts.active ?? 0) ? 'on' : ''}"><span class="pill">${ic(MNAV[i] === 'more' ? 'more2' : MNAV[i], 22)}</span>${n}${i === 2 ? '<span class="bd">14</span>' : ''}</a>`).join('')}</div>`;
  return `<!doctype html><html><head><meta charset="utf-8"><link href="https://fonts.googleapis.com/css2?${fams}&display=swap" rel="stylesheet"><style>${mcss(s)}</style></head><body><div class="sbar"><span>9:41</span><span>●●● ▮</span></div>${app}<div class="scr" style="${opts.scr || ''}">${body}</div>${nav}${opts.extra || ''}</body></html>`;
};
const mrow = (s, r, i) => `<div class="card item"><div class="bar"><span class="avs">${initials(r[1])}</span><b style="flex:1">${r[1]}</b><b class="mono" style="font-size:16px">${r[3]}</b></div><div class="bar"><span class="mono muted">${r[0]}</span><span class="muted" style="font-size:14px">${r[4]}</span><span style="margin-left:auto">${chip(r[5], s)}</span></div></div>`;
const mscreens = {
  records: s => mphone(s, T.records, `<div class="field" style="color:var(--m);height:48px">${ic('search', 18)}<span style="flex:1;margin-left:8px">${T.search}</span>${ic('filter', 18)}</div><div class="bar" style="gap:8px;overflow:hidden"><span class="fc on">${T.st.pending} ✕</span><span class="fc">${T.filters[1]} ${ic('chevron', 14)}</span><span class="fc">${T.filters[2]} ${ic('chevron', 14)}</span></div>${genRows(5).map((r, i) => mrow(s, r, i)).join('')}`, { active: 1, extra: `<div class="fab">${ic('plus', 22)}</div>`, search: false }),
  approval: s => mphone(s, T.approval, `<div class="card item" style="gap:10px"><div class="bar"><span class="avs">CP</span><b style="flex:1">Chao Phraya Logistics</b>${chip('pending', s)}</div><div class="mono" style="font-size:28px;font-weight:700">฿ 326,900.00</div><div class="muted" style="font-size:14px">${T.acct}: •••• 7734 · ${T.req} Somchai P.</div></div><div class="flag" style="color:${s.warn[0]};background:${s.warn[1]}">${ic('alert', 18)}<span>${T.changed}</span></div><div class="card item" style="gap:6px">${T.checks.map((c, i) => `<div class="bar" style="gap:8px;align-items:flex-start;color:${i < 2 ? s.ok[0] : 'var(--m)'};font-size:15px">${ic(i < 2 ? 'check' : 'clock', 17)}<span>${c}</span></div>`).join('')}</div><div class="field" style="height:64px;color:var(--m);align-items:flex-start;padding-top:12px">${T.reason}</div>`, { back: 1, active: 2, noNav: true, search: false, extra: `<div class="decide"><span class="btn full">${T.reject}</span><span class="btn p full">${ic('check', 18)}${T.approve}</span></div>`, scr: 'bottom:92px' }),
  overview: s => mphone(s, T.nav[0], `<div><div class="muted" style="font-size:14px">${T.overviewSub}</div><b style="font-size:20px">${T.greet}</b></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${[['14', T.kpis[0], 0], ['฿ 1.28M', T.kpis[1], 0], ['3', T.kpis[2], 1], ['42 min', T.kpis[3], 0]].map(k => `<div class="card kpi"><span class="muted" style="font-size:13px">${k[1]}</span><div class="v" style="${k[2] ? 'color:' + s.bad[0] : ''}">${k[2] ? '▲ ' : ''}${k[0]}</div></div>`).join('')}</div><div class="card" style="padding:14px;display:flex;flex-direction:column;height:200px"><b style="font-size:15px">${T.chart}</b>${barChart(s, [18, 34, 52, 71, 60, 88, 95, 80, 64], ['8', '9', '10', '11', '12', '13', '14', '15', '16'], { avg: 55, every: 2 })}</div><b>${T.exc}</b>${T.excs.slice(0, 2).map((e, i) => `<div class="card item" style="flex-direction:row;align-items:center;gap:10px;color:${i === 0 ? s.bad[0] : 'var(--ink)'}">${ic(i === 0 ? 'alert' : 'clock', 18)}<span style="flex:1;font-size:15px">${e}</span>${ic('chevR', 18)}</div>`).join('')}`, { active: 0 }),
  inbox: s => mphone(s, T.inbox, `<div class="bar" style="gap:8px"><span class="fc on">${T.assign}</span><span class="fc">${T.prio[0]}</span><span class="fc">${T.sla}</span></div><div class="swipe"><div class="act">${ic('check', 20)}${T.swipe}</div><div class="card item row"><div class="bar"><b style="flex:1">${T.tasks[0][0]}</b>${sevChip(0, s).replace(T.sev[0], T.prio[0])}</div><div class="bar"><span class="mono muted">${T.tasks[0][1]}</span><span class="muted" style="font-size:14px;margin-left:auto">${T.tasks[0][2]}</span></div></div></div>${T.tasks.slice(1, 6).map((t, i) => `<div class="card item"><div class="bar"><b style="flex:1">${t[0]}</b>${sevChip([0, 1, 1, 2, 2][i], s).replace(T.sev[[0, 1, 1, 2, 2][i]], T.prio[[0, 1, 1, 2, 2][i]])}</div><div class="bar"><span class="mono muted">${t[1]}</span><span style="font-size:14px;margin-left:auto;color:${i === 0 ? s.bad[0] : 'var(--m)'};font-weight:${i === 0 ? 700 : 400}">${i === 0 ? '▲ ' : ''}${t[2]}</span></div></div>`).join('')}`, { active: 2, search: false }),
  detail: s => mphone(s, 'PAY-20929', `<div class="bar" style="gap:8px">${chip('pending', s)}</div><div class="tabs"><span class="tab on">${T.tabs[0]}</span><span class="tab">${T.tabs[1]}</span><span class="tab">${T.tabs[2]}</span></div><div class="card item" style="gap:12px"><div class="kv"><span class="muted">${T.payee}</span><b>Chao Phraya Logistics</b><span class="muted">${T.amount}</span><b class="mono" style="font-size:18px">฿ 326,900.00</b><span class="muted">${T.acct}</span><span class="mono">•••• 7734</span><span class="muted">${T.req}</span><span>Somchai P.</span></div></div><div class="card item"><b>${T.tabs[1]}</b><div class="tl">${T.tl.slice(0, 4).map((t, i) => `<div><b>${T.tlt[i]}</b><span style="font-size:15px">${t}</span></div>`).join('')}</div></div>`, { back: 1, active: 1, noNav: true, search: false, extra: `<div class="decide"><span class="btn full">${T.reject}</span><span class="btn p full">${T.approve}</span></div>`, scr: 'bottom:92px' }),
  form: s => mphone(s, T.form, `<div><div style="font-weight:700;margin-bottom:6px">${T.lab[0]}</div><span class="field">${ic('search', 18)}<span style="flex:1;margin-left:8px">Chao Phraya Logistics</span></span></div><div><div style="font-weight:700;margin-bottom:6px">${T.lab[1]}</div><span class="field" style="border-color:${s.bad[0]};border-width:2px">123456789</span><div class="bar" style="color:${s.bad[0]};font-size:14px;margin-top:6px;gap:6px;font-weight:600;align-items:flex-start">${ic('alert', 15)}<span>${T.ferr}</span></div></div><div><div style="font-weight:700;margin-bottom:6px">${T.lab[2]}</div><span class="field mono" style="justify-content:flex-end;font-size:18px">326,900.00</span></div><div><div style="font-weight:700;margin-bottom:6px">${T.lab[3]}</div><span class="field">${ic('calendar', 18)}<span style="flex:1;margin-left:8px">12 Nov 2026</span></span></div>`, { back: 1, active: 1, noNav: true, search: false, extra: `<div class="decide"><span class="btn full">${T.draft}</span><span class="btn p full">${T.submit}</span></div>`, scr: 'bottom:92px' }),
  menu: s => mphone(s, T.records, `${genRows(3).map((r, i) => mrow(s, r, i)).join('')}`, { active: 1, search: false, extra: `<div class="scrim"></div><div class="drawer"><div class="bar" style="padding:0 14px 16px"><b style="font-size:20px">Plume Pay</b><span style="margin-left:auto">${ic('close', 22)}</span></div>${T.nav.map((n, i) => `<a class="${i === 1 ? 'on' : ''}">${ic(NAVI[i], 22)}${n}${i === 2 ? '<span style="margin-left:auto;font-size:13px">14</span>' : ''}</a>`).join('')}<div style="margin-top:auto;display:flex;gap:10px;align-items:center;padding:12px 14px"><span class="avs" style="background:var(--a);color:var(--ai)">NS</span><span><b>${T.user}</b><br><span style="font-size:13px;opacity:.7">${T.role}</span></span></div></div>` }),
  filter: s => mphone(s, T.records, `${genRows(3).map((r, i) => mrow(s, r, i)).join('')}`, { active: 1, search: false, extra: `<div class="scrim"></div><div class="sheet"><div class="grab"></div><div class="bar"><b style="font-size:18px">${T.filtersT}</b><span style="margin-left:auto;color:var(--a);font-weight:700">${T.clearAll}</span></div><div><div class="muted" style="font-size:14px;margin-bottom:8px">${T.statusF}</div><div class="bar" style="flex-wrap:wrap;gap:8px"><span class="fc on">${T.st.pending}</span><span class="fc">${T.st.approved}</span><span class="fc">${T.st.paid}</span><span class="fc">${T.st.failed}</span></div></div><div><div class="muted" style="font-size:14px;margin-bottom:8px">${T.dateF}</div><div class="bar" style="flex-wrap:wrap;gap:8px"><span class="fc">${L('Today', 'วันนี้')}</span><span class="fc on">${T.filters[1]}</span><span class="fc">${L('30 days', '30 วัน')}</span></div></div><div><div class="muted" style="font-size:14px;margin-bottom:8px">${T.methodF}</div><div class="bar" style="flex-wrap:wrap;gap:8px">${T.methods.map((m, i) => `<span class="fc ${i === 0 ? 'on' : ''}">${m}</span>`).join('')}</div></div><span class="btn p">${T.apply}</span></div>` })
};
mscreens.states = s => { const ph = (t, body) => `<div style="position:relative;width:390px;height:520px;background:var(--g);border-radius:0;overflow:hidden;flex:none"><div class="app" style="position:absolute;top:0;left:0;right:0"><span class="ib"></span><h1>${t}</h1></div><div class="scr" style="top:58px;bottom:0">${body}</div></div>`;
  const fams = [...new Set([s.font, s.displayFont, 'DM Mono', 'Noto Sans Thai'].filter(Boolean))].map(f => 'family=' + f.replace(/ /g, '+')).join('&');
  return `<!doctype html><html><head><meta charset="utf-8"><link href="https://fonts.googleapis.com/css2?${fams}&display=swap" rel="stylesheet"><style>${mcss(s)}body{width:1210px;height:auto;display:flex;gap:20px;background:#9aa0a8;padding:20px}</style></head><body>
${ph(L('Loading', 'กำลังโหลด'), `<div class="bar" style="gap:10px"><i class="spin"></i><span class="muted">${L('Loading payments…', 'กำลังโหลด…')}</span></div>${Array.from({ length: 4 }, () => `<div class="card item"><div class="skel" style="width:60%"></div><div class="skel" style="width:85%"></div><div class="skel" style="width:40%"></div></div>`).join('')}`)}
${ph(L('Empty', 'ว่าง'), `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center"><div class="avs" style="width:64px;height:64px">${ic('search', 28)}</div><b style="font-size:18px">${L('No payments match', 'ไม่พบรายการที่ตรง')}</b><span class="muted">${L('Try fewer filters.', 'ลองลดตัวกรอง')}</span><span class="btn p">${L('Clear filters', 'ล้างตัวกรอง')}</span></div>`)}
${ph(L('Error', 'ข้อผิดพลาด'), `<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center"><div class="avs" style="width:64px;height:64px;background:${s.bad[1]};color:${s.bad[0]}">${ic('alert', 28)}</div><b style="font-size:18px">${L('Could not load payments', 'โหลดรายการจ่ายไม่สำเร็จ')}</b><span class="muted">${L('Check your connection. Your filters are kept.', 'ตรวจการเชื่อมต่อ ตัวกรองของคุณยังอยู่')}</span><span class="btn p">${L('Try again', 'ลองอีกครั้ง')}</span></div>`)}</body></html>`; };
mscreens.components = s => { const fams = [...new Set([s.font, s.displayFont, 'DM Mono', 'Noto Sans Thai'].filter(Boolean))].map(f => 'family=' + f.replace(/ /g, '+')).join('&');
  const blk = (t, h) => `<div><div class="muted" style="font:700 12px 'DM Mono',monospace;margin-bottom:8px">${t}</div><div style="display:flex;flex-direction:column;gap:10px">${h}</div></div>`;
  const body = `${blk(L('App bars', 'แถบบนสุด'), `<div class="app card" style="height:56px;border-radius:var(--r)"><span class="ib">${ic('more2', 22)}</span><h1>${T.records}</h1><span class="ib">${ic('search', 21)}</span><span class="ib">${ic('bell', 21)}<i></i></span></div><div class="app card" style="height:56px"><span class="ib">${ic('back', 22)}</span><h1>PAY-20929</h1><span class="ib">${ic('more', 21)}</span></div><div class="card" style="padding:14px 16px"><div class="muted" style="font-size:13px">${T.nav[1]}</div><b style="font-size:28px;font-family:'${s.font}'">${T.records}</b></div>`)}
${blk(L('Bottom navigation', 'เมนูล่าง'), `<div class="card" style="display:flex;padding:8px 6px 10px">${T.mnav.map((n, i) => `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:11px;font-weight:600;color:${i === 1 ? 'var(--ink)' : 'var(--m)'};position:relative"><span style="height:30px;width:58px;border-radius:99px;display:grid;place-items:center;background:${i === 1 ? 'var(--as)' : 'transparent'}">${ic(MNAV[i] === 'more' ? 'more2' : MNAV[i], 22)}</span>${n}${i === 2 ? `<span style="position:absolute;top:-2px;left:50%;margin-left:8px;min-width:18px;height:18px;border-radius:99px;background:${s.bad[0]};color:#fff;font-size:11px;display:grid;place-items:center;padding:0 5px">14</span>` : ''}</div>`).join('')}</div>`)}
${blk(L('Floating action button', 'ปุ่มลอย'), `<div class="bar"><span class="fab" style="position:static">${ic('plus', 22)}</span><span class="fab" style="position:static">${ic('plus', 20)}${T.newp}</span></div>`)}
${blk(L('Buttons and fields (48px+ touch)', 'ปุ่มและช่องกรอก (สัมผัสได้ 48px+)'), `<div class="bar"><span class="btn p full">${T.approve}</span><span class="btn full">${T.reject}</span></div><span class="btn" style="color:${s.bad[0]};border-color:${s.bad[0]}">${ic('alert', 18)}${L('Delete payee', 'ลบผู้รับเงิน')}</span><span class="field">${T.lab[0]}</span><span class="field" style="border-color:${s.bad[0]};border-width:2px">123456789</span><div class="bar" style="color:${s.bad[0]};font-size:14px;gap:6px;font-weight:600">${ic('alert', 15)}${T.ferr}</div>`)}
${blk(L('Filter chips and segmented', 'ชิปตัวกรองและสลับมุมมอง'), `<div class="bar" style="gap:8px;overflow:hidden"><span class="fc on">${T.st.pending} ✕</span><span class="fc">${T.filters[1]} ${ic('chevron', 14)}</span><span class="fc">${T.filters[2]} ${ic('chevron', 14)}</span></div><div class="card" style="display:flex;padding:4px;gap:4px">${[L('Day', 'วัน'), L('Week', 'สัปดาห์'), L('Month', 'เดือน')].map((t, i) => `<span class="btn" style="flex:1;height:40px;border:none;${i === 1 ? 'background:var(--as)' : 'background:transparent;color:var(--m)'}">${t}</span>`).join('')}</div>`)}
${blk(L('List item with swipe action', 'รายการที่ปัดเพื่อทำงาน'), `<div class="swipe"><div class="act">${ic('check', 20)}${T.swipe}</div><div class="card item row"><div class="bar"><b style="flex:1">${T.tasks[0][0]}</b></div><div class="mono muted">${T.tasks[0][1]}</div></div></div><div class="card item"><div class="bar"><span class="avs">SF</span><b style="flex:1">Siam Fresh Co.</b><b class="mono">48,200.00</b></div><div class="bar">${chip('failed', s)}</div></div>`)}
${blk(L('Bottom sheet, snackbar, pull to refresh', 'ชีตล่าง ป๊อปอัปแจ้ง และดึงรีเฟรช'), `<div class="card" style="padding:10px 16px 16px;display:flex;flex-direction:column;gap:10px;border-radius:20px 20px 0 0"><div style="width:40px;height:5px;border-radius:99px;background:var(--ln);margin:0 auto"></div><b>${T.filtersT}</b><div class="bar" style="gap:8px"><span class="fc on">${T.st.pending}</span><span class="fc">${T.st.paid}</span></div><span class="btn p">${T.apply}</span></div><div class="snack" style="position:static;z-index:0">${ic('check', 18)}<span style="flex:1">${T.snack}</span><b style="text-decoration:underline">${T.undo}</b></div><div class="bar muted" style="justify-content:center;gap:8px"><i class="spin"></i>${T.pull}</div>`)}
${blk(L('Settings rows and dialog', 'แถวตั้งค่าและกล่องยืนยัน'), `<div class="card item" style="gap:14px"><div class="bar"><span style="flex:1">${T.t[0]}</span><span class="tog"></span></div><div class="bar"><span style="flex:1">${T.t[3]}</span><span class="tog off"></span></div></div><div class="card item" style="gap:12px;box-shadow:0 12px 36px rgba(0,0,0,.25)"><b style="font-size:18px">${L('Reject 2 payments?', 'ปฏิเสธ 2 รายการ?')}</b><span class="muted">${L('The requesters will be told. This cannot be undone.', 'ผู้ขอจะได้รับแจ้ง และเลิกทำไม่ได้')}</span><div class="bar"><span class="btn full">${L('Cancel', 'ยกเลิก')}</span><span class="btn full" style="background:${s.bad[0]};color:#fff;border-color:${s.bad[0]}">${L('Reject 2', 'ปฏิเสธ 2 รายการ')}</span></div></div>`)}`;
  return `<!doctype html><html><head><meta charset="utf-8"><link href="https://fonts.googleapis.com/css2?${fams}&display=swap" rel="stylesheet"><style>${mcss(s)}body{height:auto;overflow:visible;padding:16px;display:flex;flex-direction:column;gap:22px}.scr{position:static}</style></head><body><div><b style="font-size:20px">${s.name}</b> <span class="muted">${L('mobile components · sample', 'คอมโพเนนต์มือถือ · ตัวอย่าง')}</span></div>${body}</body></html>`; };

(async () => {
  const mod = findModule(process.cwd());
  const exe = mod ? findBrowser(mod.chromium) : undefined;
  if (!mod || exe === undefined) { console.log('NOT RUN: no Playwright module or browser (npm i -D playwright && npx playwright install chromium)'); process.exit(3); }
  fs.mkdirSync(out, { recursive: true });
  const browser = await mod.chromium.launch(exe ? { executablePath: exe } : {});
  const page = await browser.newPage({ viewport: { width: W, height: H } });
  const src = mobile ? mscreens : screens;
  const mp = mobile ? 'm-' : '';
  const file = (st, sc) => path.join(out, `${st}-${mp}${sc}${thai ? '-th' : ''}.jpg`);
  for (const st of pickS) for (const sc of pickC) {
    await page.setViewportSize({ width: mobile && sc === 'states' ? 1250 : W, height: H });
    await page.setContent(rtlify(src[sc](st)), { waitUntil: 'load', timeout: 30000 }).catch(() => {});
    await page.evaluate(() => document.fonts && document.fonts.ready).catch(() => {});
    await page.waitForTimeout(250);
    if (TALL.includes(sc)) await page.screenshot({ path: file(st.id, sc), type: 'jpeg', quality: 70, fullPage: true });
    else await page.screenshot({ path: file(st.id, sc), type: 'jpeg', quality: 74, clip: { x: 0, y: 0, width: W, height: H } });
    console.log(`${st.id}-${mp}${sc} → ${file(st.id, sc)}`);
  }
  if (has('--sheet')) {
    const sheet = async (items, name, cols) => {
      const tw = cols === 2 ? 720 : cols === 3 ? 600 : cols === 5 ? 380 : cols === 6 ? 250 : 440, th = Math.round(tw * H / W);
      const cells = items.map(([st, sc]) => `<figure style="margin:0"><img src="data:image/jpeg;base64,${fs.readFileSync(file(st.id, sc)).toString('base64')}" width="${tw}" height="${th}" style="display:block;border:1px solid #ccc"><figcaption style="font:600 16px system-ui;padding:6px 2px">${st.name} <span style="font-weight:400;color:#666">${sc}</span></figcaption></figure>`).join('');
      await page.setViewportSize({ width: cols * (tw + 24) + 24, height: 400 });
      await page.setContent(`<body style="margin:0;padding:24px;background:#fff"><div style="display:grid;grid-template-columns:repeat(${cols},${tw}px);gap:20px 24px">${cells}</div></body>`, { waitUntil: 'load' });
      await page.waitForTimeout(250);
      await page.screenshot({ path: path.join(out, `${name}${thai ? '-th' : ''}.jpg`), type: 'jpeg', quality: 62, fullPage: true });
      console.log(`${name} → ${path.join(out, name + '.jpg')}`);
    };
    const flat = pickC.filter(sc => !TALL.includes(sc));
    for (const sc of flat) await sheet(pickS.map(st => [st, sc]), `sheet-${mp}${sc}`, pickS.length > 6 ? (mobile ? 6 : 4) : 2);
    if (has('--style-sheets')) for (const st of pickS) await sheet(flat.map(sc => [st, sc]), `sheet-${mp}${st.id}`, flat.length > 8 ? 5 : 3);
  }
  if (singles !== 'all' && !has('--out')) {
    const keep = singles.split(',').concat(TALL);
    for (const st of pickS) for (const sc of pickC) if (!keep.includes(sc)) { try { fs.unlinkSync(file(st.id, sc)); } catch (e) {} }
  }
  await browser.close();
})();
